#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=11

# Staging, komplett getrennt von Live: eigenes Supabase-Projekt, eigene Netlify-Site aus
# Branch "staging", Dropbox-App mit App-Ordner, SharePoint "Medienablage-Test".
# Schreibt nach .env.staging (Vite lädt sie mit --mode staging).
# Voraussetzung: Schritt 2 erledigt (MS_* und SP_TEST_* in .env).
# Aufruf: bash scripts/medienablage/3-staging-einrichten.sh

ENV_FILE=".env.staging"
PROD_ENV=".env"
SECRETS_DIR=".secrets"
NETLIFY_IMPORT="$SECRETS_DIR/netlify-staging.env"
mkdir -p "$SECRETS_DIR"; chmod 700 "$SECRETS_DIR"

prod_value() { ENV_FILE="$PROD_ENV" _existing "$1" || true; }

banner "Medienablage · Schritt 3: Staging einrichten"

stage "Werkzeuge"
for bin in git supabase psql node openssl; do
  if command -v "$bin" >/dev/null 2>&1; then printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$bin"
  else warn "$bin fehlt"; fi
done
command -v psql >/dev/null 2>&1 || note "psql: brew install libpq && brew link --force libpq"
command -v supabase >/dev/null 2>&1 || note "supabase: brew install supabase/tap/supabase"
pause

stage "Branch staging"
say "Die Staging-Site baut aus dem Branch 'staging'. Er startet auf dem Stand von v2."
note "Regel: feat/medienablage → staging (testen) → v2 nur mit Weichen auf dropbox, nicht mitten am Arbeitstag."
if git show-ref --verify --quiet refs/heads/staging; then
  note "Branch staging existiert schon."
elif confirm "Branch staging aus v2 anlegen und pushen?"; then
  git branch staging v2 && git push -u origin staging
fi
pause

stage "Supabase-Projekt anlegen"
open_url "https://supabase.com/dashboard/new"
step "Name: crm-staging  ·  Region: Central EU (Frankfurt)  ·  Datenbank-Passwort merken"
step "Nach dem Anlegen: Project Settings → API → Project URL, anon key, service_role key kopieren"
ask VITE_SUPABASE_URL "Project URL (https://….supabase.co):"
ask VITE_SUPABASE_ANON_KEY "anon key:"
ask_secret SUPABASE_SERVICE_ROLE_KEY "service_role key:"
write_env VITE_SUPABASE_URL "$VITE_SUPABASE_URL"
write_env VITE_SUPABASE_ANON_KEY "$VITE_SUPABASE_ANON_KEY"
write_env SUPABASE_URL "$VITE_SUPABASE_URL"
write_env SUPABASE_SERVICE_ROLE_KEY "$SUPABASE_SERVICE_ROLE_KEY"
write_env SUPABASE_SERVICE_KEY "$SUPABASE_SERVICE_ROLE_KEY"
step "Connect (oben) → 'Session pooler' → URI mit Passwort kopieren"
ask_secret STAGING_DB_URL "Staging-DB-URL (postgresql://…):"
write_env STAGING_DB_URL "$STAGING_DB_URL"
write_env VITE_APP_CHANNEL "staging"
pause

stage "Schema aus der Produktion übernehmen"
say "Die Repo-Migrationen sind unvollständig (Dashboard-Policies, keine config.toml)."
say "Darum: Schema der Produktion als Dump, ohne Daten."
step "Live-Dashboard → Connect → Session pooler → URI kopieren (nur für diesen Lauf, wird nicht gespeichert)"
ask_secret PROD_DB_URL "Live-DB-URL (postgresql://…):"
if confirm "Schema-Dump ziehen und in Staging einspielen?"; then
  supabase db dump --db-url "$PROD_DB_URL" --schema public,private -f "$SECRETS_DIR/prod-schema.sql"
  psql "$STAGING_DB_URL" -v ON_ERROR_STOP=0 -q -f "$SECRETS_DIR/prod-schema.sql" 2>&1 | tail -n 20
  note "Fehler zu bereits vorhandenen Objekten (extensions, Rollen) sind normal."
fi
unset PROD_DB_URL
pause

stage "Noch nicht live angewendete Migrationen"
for f in supabase/migrations/20261129_asset_poster.sql \
         supabase/migrations/20261130_custom_column_assets_rls.sql \
         supabase/migrations/20261201_medienablage.sql \
         supabase/migrations/20261202_medienablage_creator_umzug.sql; do
  if [[ -f "$f" ]] && confirm "$f auf Staging anwenden?"; then
    psql "$STAGING_DB_URL" -v ON_ERROR_STOP=1 -q -f "$f" && printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$f"
  fi
done
pause

stage "Admin-Login in Staging"
open_url "https://supabase.com/dashboard/project/_/auth/users"
step "Staging-Projekt wählen → Add user → Create new user → E-Mail + Passwort, 'Auto Confirm' an"
ask STAGING_ADMIN_EMAIL "E-Mail dieses Logins:"
write_env STAGING_ADMIN_EMAIL "$STAGING_ADMIN_EMAIL"
pause

stage "Testdaten einspielen"
say "Zwei Test-Unternehmen (eines auf SharePoint, eines auf Dropbox), doppelte Kooperationsnamen."
if confirm "Seed jetzt einspielen?"; then
  psql "$STAGING_DB_URL" -v ON_ERROR_STOP=1 -v admin_email="$STAGING_ADMIN_EMAIL" \
    -q -f scripts/medienablage/staging-seed.sql && printf '  %s✓%s Seed\n' "$GREEN" "$RESET"
fi
pause

stage "Dropbox-App nur für Staging"
say "Eigene App mit App-Ordner: Staging kann nie ins echte Dropbox schreiben."
open_url "https://www.dropbox.com/developers/apps/create"
step "Scoped access → App folder → Name z. B. 'CRM Staging Medienablage'"
step "Permissions: files.metadata.write, files.content.write, files.content.read, sharing.write → Submit"
step "Settings: App key und App secret kopieren"
ask DROPBOX_APP_KEY "App key:"
ask_secret DROPBOX_APP_SECRET "App secret:"
write_env DROPBOX_APP_KEY "$DROPBOX_APP_KEY"
write_env DROPBOX_APP_SECRET "$DROPBOX_APP_SECRET"
open_url "https://www.dropbox.com/oauth2/authorize?client_id=${DROPBOX_APP_KEY}&response_type=code&token_access_type=offline"
step "Zulassen → den angezeigten Code kopieren"
ask_secret DROPBOX_CODE "Autorisierungscode:"
DROPBOX_REFRESH_TOKEN=$(curl -s https://api.dropboxapi.com/oauth2/token \
  -d code="$DROPBOX_CODE" -d grant_type=authorization_code \
  -u "${DROPBOX_APP_KEY}:${DROPBOX_APP_SECRET}" | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{try{process.stdout.write(JSON.parse(s).refresh_token||"")}catch{}})')
if [[ -n "$DROPBOX_REFRESH_TOKEN" ]]; then write_env DROPBOX_REFRESH_TOKEN "$DROPBOX_REFRESH_TOKEN"
else warn "Kein Refresh-Token erhalten (Code abgelaufen?). Stufe wiederholen."; fi
pause

stage "Zertifikat in den Staging-Vault"
if confirm "Schlüssel und Zertifikat aus .secrets in den Staging-Vault schreiben?"; then
  node scripts/medienablage/vault-setzen.mjs --env "$ENV_FILE" \
    --key "$SECRETS_DIR/medienablage-app.key" --cert "$SECRETS_DIR/medienablage-app.crt" \
    || warn "Fehlgeschlagen: Ausgabe oben prüfen."
fi
pause

stage "Netlify-Site für Staging"
open_url "https://app.netlify.com/start"
step "Import an existing project → gleiches Repo → Branch to deploy: staging"
step "Build-Einstellungen kommen aus netlify.toml. Site-Name z. B. crm-staging-medienablage"
note "Eigene Site statt Branch-Deploy: Scheduled Functions laufen nur auf dem Production-Deploy einer Site."
ask STAGING_SITE_URL "URL der Staging-Site (https://….netlify.app):"
write_env STAGING_SITE_URL "$STAGING_SITE_URL"
# Einmal erzeugt, dann aus .env.staging, damit ein zweiter Lauf dieselben Werte exportiert.
for k in POSTER_SECRET CREATOR_UPLOAD_TOKEN_KEY ABLAGE_SECRET SP_WEBHOOK_CLIENT_STATE; do
  [[ -n "$(_existing "$k" || true)" ]] || write_env "$k" "$(openssl rand -hex 32)"
done
umask 077
{
  printf 'VITE_SUPABASE_URL=%s\n' "$VITE_SUPABASE_URL"
  printf 'VITE_SUPABASE_ANON_KEY=%s\n' "$VITE_SUPABASE_ANON_KEY"
  printf 'SUPABASE_URL=%s\n' "$VITE_SUPABASE_URL"
  printf 'SUPABASE_ANON_KEY=%s\n' "$VITE_SUPABASE_ANON_KEY"
  printf 'SUPABASE_SERVICE_ROLE_KEY=%s\n' "$SUPABASE_SERVICE_ROLE_KEY"
  printf 'SUPABASE_SERVICE_KEY=%s\n' "$SUPABASE_SERVICE_ROLE_KEY"
  printf 'VITE_APP_CHANNEL=staging\n'
  printf 'APP_BASE_URL=%s\n' "$STAGING_SITE_URL"
  printf 'DROPBOX_APP_KEY=%s\n' "$DROPBOX_APP_KEY"
  printf 'DROPBOX_APP_SECRET=%s\n' "$DROPBOX_APP_SECRET"
  printf 'DROPBOX_REFRESH_TOKEN=%s\n' "$(_existing DROPBOX_REFRESH_TOKEN || true)"
  printf 'POSTER_SECRET=%s\n' "$(_existing POSTER_SECRET || true)"
  printf 'CREATOR_UPLOAD_TOKEN_KEY=%s\n' "$(_existing CREATOR_UPLOAD_TOKEN_KEY || true)"
  printf 'ABLAGE_SECRET=%s\n' "$(_existing ABLAGE_SECRET || true)"
  printf 'MS_TENANT_ID=%s\n' "$(prod_value MS_TENANT_ID)"
  printf 'MS_CLIENT_ID=%s\n' "$(prod_value MS_CLIENT_ID)"
  printf 'SP_SITE_URL=%s\n' "$(prod_value SP_TEST_SITE_URL)"
  printf 'SP_SITE_ID=%s\n' "$(prod_value SP_TEST_SITE_ID)"
  printf 'SP_DRIVE_ID=%s\n' "$(prod_value SP_TEST_DRIVE_ID)"
  printf 'SP_WEBHOOK_CLIENT_STATE=%s\n' "$(_existing SP_WEBHOOK_CLIENT_STATE || true)"
} > "$NETLIFY_IMPORT"
for k in MS_TENANT_ID MS_CLIENT_ID; do write_env "$k" "$(prod_value "$k")"; done
write_env SP_SITE_URL "$(prod_value SP_TEST_SITE_URL)"
write_env SP_SITE_ID "$(prod_value SP_TEST_SITE_ID)"
write_env SP_DRIVE_ID "$(prod_value SP_TEST_DRIVE_ID)"
step "Staging-Site → Site configuration → Environment variables → Import from a .env file"
step "Inhalt von $(pwd)/$NETLIFY_IMPORT einfügen → Deploy auslösen"
note "RESEND_API_KEY bewusst leer: Staging verschickt keine Mails, Alerts landen nur im Log."
pause "Importiert und deployt? Enter"

finish
note "Lokal gegen Staging: npx vite --mode staging --port 3002"
note "Prototyp: node scripts/medienablage-spike.mjs --env .env.staging"
